// CreateCustomers adds customers in order, all or none. The caller checks each record's name, email address and payment
// method. When an email address is used by one of the organization's customers, or by an earlier record, nothing is
// created and the indexes of those records are returned. The check and the creation happen under one lock.
func (s *Store) CreateCustomers(orgID string, recs []Customer, now time.Time) ([]Customer, []int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return nil, nil, ErrNotFound
	}
	emails := make([]string, len(recs))
	for i, r := range recs {
		emails[i] = r.Email
	}
	if taken := s.takenEmails(orgID, emails); len(taken) > 0 {
		return nil, taken, nil
	}
	out := make([]Customer, 0, len(recs))
	for _, r := range recs {
		c := r
		c.ID, c.OrgID = s.newID("cus"), orgID
		c.Name, c.Email, c.CreatedAt = strings.TrimSpace(r.Name), strings.TrimSpace(r.Email), now.UTC()
		c = copyCustomer(c)
		s.customers[c.ID] = c
		s.customersByEmail[normEmail(c.Email)] = c.ID
		out = append(out, copyCustomer(c))
	}
