		{Name: "Bo", Email: "bo@example.com"},
	}
	got, taken, err := s.CreateCustomers(a.ID, recs, t0)
	if err != nil || len(taken) != 0 || len(got) != 2 || got[0].Name != "Ann" || got[0].Email != "ann@example.com" || got[0].OrgID != a.ID {
		t.Fatalf("CreateCustomers = %+v, %v, %v", got, taken, err)
	}
	if c, ok := s.FindCustomerByEmail(a.ID, "BO@example.com"); !ok || c.ID != got[1].ID {
		t.Fatalf("created customer not found by email: %+v %v", c, ok)
	}
	if _, ok := s.Customer(b.ID, got[0].ID); ok {
		t.Fatal("created customer is visible to another org")
	}

	// One address is used by an existing customer and another repeats within the batch: nothing is created.
	before := len(s.Customers(a.ID))
	recs = []Customer{
		{Name: "Cy", Email: "cy@example.com"},
		{Name: "Jane 2", Email: "JANE@example.com"},
		{Name: "Di", Email: "di@example.com"},
		{Name: "Di 2", Email: "Di@example.com"},
	}
