		t.Fatalf("CreateCustomers = %+v, %v, %v", got, taken, err)
	}
	if n := len(s.Customers(a.ID)); n != before {
		t.Fatalf("a refused batch created %d customers", n-before)
	}
	if _, err := s.CreateCustomer(a.ID, "Cy", "cy@example.com", t0); err != nil {
		t.Fatalf("email of a refused batch is still taken: %v", err)
	}

	if _, _, err := s.CreateCustomers("org_missing", recs, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown org: %v", err)
	}
	if got := s.CustomerEmailsTaken(a.ID, []string{"x@example.com", "JANE@example.com", "cy@example.com"}); len(got) != 2 || got[0] != 1 || got[1] != 2 {
		t.Fatalf("CustomerEmailsTaken = %v", got)
