	}
	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("dry run of a bad file: %s", r)
	}

	csvOf := func(n int) string {
		var b strings.Builder
		b.WriteString("name,email\n")
