			fmt.Fprintf(&b, "Customer %d,c%d@example.com\n", i, i)
		}
		return b.String()
	}
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, csvOf(maxImportRows+1)); r.Code != http.StatusRequestEntityTooLarge || r.Map(t)["error"] != "too_many_rows" {
