31	// CreateCustomers adds customers in order, all or none. The caller checks each record's name, email address and payment
32	// method. When an email address is used by one of the organization's customers, or by an earlier record, nothing is
33	// created and the indexes of those records are returned. The check and the creation happen under one lock.
34	func (s *Store) CreateCustomers(orgID string, recs []Customer, now time.Time) ([]Customer, []int, error) {
35		s.mu.Lock()
36		defer s.mu.Unlock()
37		if _, ok := s.orgs[orgID]; !ok {
38			return nil, nil, ErrNotFound
39		}
40		var taken []int
41		seen := map[string]bool{}
42		for i, r := range recs {
43			key := normEmail(r.Email)
44			id, exists := s.customersByEmail[key]
45			if (exists && s.customers[id].OrgID == orgID) || seen[key] {
46				taken = append(taken, i)
47			}
48			seen[key] = true
49		}
50		if len(taken) > 0 {
51			return nil, taken, nil
52		}
53		out := make([]Customer, 0, len(recs))
54		for _, r := range recs {
55			c := r
56			c.ID, c.OrgID = s.newID("cus"), orgID
57			c.Name, c.Email, c.CreatedAt = strings.TrimSpace(r.Name), strings.TrimSpace(r.Email), now.UTC()
58			c = copyCustomer(c)
59			s.customers[c.ID] = c
60			s.customersByEmail[normEmail(c.Email)] = c.ID
61			out = append(out, copyCustomer(c))
62		}
63		return out, nil, nil
64	}
