135	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
136	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		old, ok := s.customers[id]
140		if !ok || old.OrgID != orgID {
141			return Customer{}, ErrNotFound
142		}
143		c := copyCustomer(old)
144		if err := f(&c); err != nil {
145			return Customer{}, err
146		}
147		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
148		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
149		if c.Name == "" || !validEmail(c.Email) {
150			return Customer{}, invalid("a customer needs a name and a valid email address")
151		}
152		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
153			return Customer{}, invalid("a payment method looks like pm_...")
154		}
155		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
156			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
157				return Customer{}, ErrEmailTaken
158			}
159			delete(s.customersByEmail, normEmail(old.Email))
160			s.customersByEmail[newKey] = c.ID
161		}
162		s.customers[id] = c
163		return copyCustomer(c), nil
164	}
