167	func (s *Store) DeleteCustomer(orgID, id string) error {
168		s.mu.Lock()
169		defer s.mu.Unlock()
170		c, ok := s.customers[id]
171		if !ok || c.OrgID != orgID {
172			return ErrNotFound
173		}
174		delete(s.customers, id)
175		if s.customersByEmail[normEmail(c.Email)] == id {
176			delete(s.customersByEmail, normEmail(c.Email))
177		}
