181	func copyCustomer(c Customer) Customer {
182		if c.Metadata != nil {
183			m := make(map[string]string, len(c.Metadata))
184			for k, v := range c.Metadata {
185				m[k] = v
186			}
187			c.Metadata = m
188		}
189		return c
190	}
