192	func sortCustomers(cs []Customer) {
193		sort.Slice(cs, func(i, j int) bool {
194			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
195				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
196			}
197			return cs[i].ID < cs[j].ID
198		})
199	}
