func customerKey(c store.Customer) cursor { return cursor{T: c.CreatedAt, ID: c.ID} }

// listCustomers lists the organization's customers, oldest first: all of them, those matching ?q= (name or email contains
// it, ignoring case), or the one with exactly ?email=.
func (s *Server) listCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	var cs []store.Customer
	switch {
	case q.Get("email") != "":
		cs = []store.Customer{}
		if c, ok := s.store.FindCustomerByEmail(p.OrgID, q.Get("email")); ok {
			cs = append(cs, c)
		}
	case q.Get("q") != "":
		cs = s.store.SearchCustomers(p.OrgID, q.Get("q"))
	default:
		cs = s.store.Customers(p.OrgID)
	}
	items, next := pageOf(cs, customerKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name                 string            `json:"name"`
		Email                string            `json:"email"`
		DefaultPaymentMethod string            `json:"default_payment_method"`
		Metadata             map[string]string `json:"metadata"`
	}
	if !decode(w, r, &in) {
		return
	}
	c, err := s.store.CreateCustomer(p.OrgID, in.Name, in.Email, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	if in.DefaultPaymentMethod != "" || len(in.Metadata) > 0 {
		c, err = s.store.UpdateCustomer(p.OrgID, c.ID, func(c *store.Customer) error {
			c.DefaultPaymentMethod, c.Metadata = in.DefaultPaymentMethod, in.Metadata
			return nil
		})
		if err != nil {
			_ = s.store.DeleteCustomer(p.OrgID, c.ID)
			s.storeError(w, err)
			return
		}
	}
	s.publish(r.Context(), p.OrgID, "customer.created", c)
	writeJSON(w, http.StatusCreated, c)
}

// maxImportRows is the most data records one import may have.
const maxImportRows = 10000

// metadataPrefix starts the header of a column that fills one metadata key, as in "metadata.crm_id".
const metadataPrefix = "metadata."

// utf8BOM starts a body that a spreadsheet saved with a byte order mark.
var utf8BOM = []byte("\xef\xbb\xbf")

// importRow is one data record of a customer import: the line its record starts on, and its values.
type importRow struct {
	line                 int
	name, email, payment string
	metadata             map[string]string
}

// importColumns are the header's column indexes (-1 when absent), and the metadata key of each metadata.<key> column by
// index.
type importColumns struct {
	count                int
	name, email, payment int
	metadata             map[int]string
}

// importProblem is a record that cannot be imported, and the first problem it has.
type importProblem struct {
	Row   int    `json:"row"`
	Error string `json:"error"`
}

// importCustomers creates the customers in a CSV body (the first record is the header): all of them, or none when any
// record has a problem. ?dry_run=true checks the body and creates nothing.
func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	rows, ok := readImportCSV(w, r.Body)
	if !ok {
		return
	}
	if problems := s.checkImportRows(p.OrgID, rows); len(problems) > 0 {
		writeInvalidRows(w, problems)
		return
	}
	if r.URL.Query().Get("dry_run") == "true" {
		writeJSON(w, http.StatusOK, map[string]int{"created": 0, "would_create": len(rows)})
		return
	}
	recs := make([]store.Customer, len(rows))
	for i, row := range rows {
		recs[i] = store.Customer{Name: row.name, Email: row.email, DefaultPaymentMethod: row.payment, Metadata: row.metadata}
	}
	created, taken, err := s.store.CreateCustomers(p.OrgID, recs, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	if len(taken) > 0 {
		// Another request took one of the addresses after the check above; nothing was created.
		var problems []importProblem
		for _, i := range taken {
			problems = append(problems, importProblem{Row: rows[i].line, Error: "email_taken"})
		}
		writeInvalidRows(w, problems)
		return
	}
	for _, c := range created {
		s.publish(r.Context(), p.OrgID, "customer.created", c)
	}
	writeJSON(w, http.StatusCreated, map[string]any{"created": len(created), "items": created})
}

// checkImportRows returns the first problem of each record that cannot be imported, in file order.
func (s *Server) checkImportRows(orgID string, rows []importRow) []importProblem {
	emails := make([]string, len(rows))
	for i, row := range rows {
		emails[i] = row.email
	}
	taken := map[int]bool{}
	for _, i := range s.store.CustomerEmailsTaken(orgID, emails) {
		taken[i] = true
	}
	var problems []importProblem
	seen := map[string]bool{}
	for i, row := range rows {
		key := strings.ToLower(row.email)
		code := ""
		switch {
		case row.name == "":
			code = "missing_name"
		case !store.ValidEmail(row.email):
			code = "invalid_email"
		case row.payment != "" && !strings.HasPrefix(row.payment, "pm_"):
			code = "invalid_payment_method"
		case taken[i]:
			code = "email_taken"
		case seen[key]:
			code = "duplicate_email"
		}
		seen[key] = true
		if code != "" {
			problems = append(problems, importProblem{Row: row.line, Error: code})
		}
	}
	return problems
}

// readImportCSV reads the header and data records of a customer import. It answers the error itself and returns false
// when the body cannot be imported.
func readImportCSV(w http.ResponseWriter, body io.Reader) ([]importRow, bool) {
	raw, err := io.ReadAll(body)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_csv"})
		return nil, false
	}
	cr := csv.NewReader(bytes.NewReader(bytes.TrimPrefix(raw, utf8BOM)))
	cr.FieldsPerRecord = -1 // checked below, so that a line of only spaces can be skipped as blank
	var (
		cols       importColumns
		haveHeader bool
		rows       []importRow
	)
	for {
		rec, err := cr.Read()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_csv"})
			return nil, false
		}
		if blank(rec) {
			continue
		}
		if !haveHeader {
			if cols, haveHeader = importHeader(rec); !haveHeader {
				writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": "invalid_header"})
				return nil, false
			}
			continue
		}
		if len(rec) != cols.count {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_csv"})
			return nil, false
		}
		if len(rows) == maxImportRows {
			writeJSON(w, http.StatusRequestEntityTooLarge, map[string]string{"error": "too_many_rows"})
			return nil, false
		}
		line, _ := cr.FieldPos(0)
		rows = append(rows, cols.row(line, rec))
	}
	if !haveHeader {
		writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": "invalid_header"})
		return nil, false
	}
	return rows, true
}

// importHeader finds the columns of a customer import's header. name and email are required; default_payment_method
// and metadata.<key> are optional; other columns are ignored. Names match ignoring case and surrounding spaces.
func importHeader(rec []string) (importColumns, bool) {
	cols := importColumns{count: len(rec), name: -1, email: -1, payment: -1, metadata: map[int]string{}}
	for i, h := range rec {
		h = strings.TrimSpace(h)
		lower := strings.ToLower(h)
		switch {
		case lower == "name" && cols.name < 0:
			cols.name = i
		case lower == "email" && cols.email < 0:
			cols.email = i
		case lower == "default_payment_method" && cols.payment < 0:
			cols.payment = i
		case len(h) > len(metadataPrefix) && strings.EqualFold(h[:len(metadataPrefix)], metadataPrefix):
			cols.metadata[i] = strings.TrimSpace(h[len(metadataPrefix):])
		}
	}
	return cols, cols.name >= 0 && cols.email >= 0
}

// row reads a data record. Empty optional cells are left out.
func (cols importColumns) row(line int, rec []string) importRow {
	row := importRow{line: line, name: strings.TrimSpace(rec[cols.name]), email: strings.TrimSpace(rec[cols.email]), metadata: map[string]string{}}
	if cols.payment >= 0 {
		row.payment = strings.TrimSpace(rec[cols.payment])
	}
	for i, key := range cols.metadata {
		if v := strings.TrimSpace(rec[i]); v != "" {
			row.metadata[key] = v
		}
	}
	return row
}

// blank reports whether a record has no text in any field.
func blank(rec []string) bool {
	for _, f := range rec {
		if strings.TrimSpace(f) != "" {
			return false
		}
	}
	return true
}

// writeInvalidRows answers 422 with the records that cannot be imported.
func writeInvalidRows(w http.ResponseWriter, problems []importProblem) {
	writeJSON(w, http.StatusUnprocessableEntity, map[string]any{"error": "invalid_rows", "rows": problems})
}

func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	c, ok := s.store.Customer(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such customer")
		return
	}
	writeJSON(w, http.StatusOK, c)
}

func (s *Server) updateCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name                 *string            `json:"name"`
		Email                *string            `json:"email"`
		DefaultPaymentMethod *string            `json:"default_payment_method"`
		Metadata             *map[string]string `json:"metadata"`
	}
	if !decode(w, r, &in) {
		return
	}
	c, err := s.store.UpdateCustomer(p.OrgID, r.PathValue("id"), func(c *store.Customer) error {
		if in.Name != nil {
			c.Name = *in.Name
		}
		if in.Email != nil {
			c.Email = *in.Email
		}
		if in.DefaultPaymentMethod != nil {
			c.DefaultPaymentMethod = *in.DefaultPaymentMethod
		}
		if in.Metadata != nil {
			c.Metadata = *in.Metadata
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "customer.updated", c)
	writeJSON(w, http.StatusOK, c)
}

func (s *Server) deleteCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	id := r.PathValue("id")
	if err := s.store.DeleteCustomer(p.OrgID, id); err != nil {
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "customer.deleted", map[string]string{"id": id})
	w.WriteHeader(http.StatusNoContent)
}

// exportCustomers answers the organization's customers as CSV, oldest first.
func (s *Server) exportCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	w.Header().Set("Content-Type", "text/csv; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="customers.csv"`)
	cw := csv.NewWriter(w)
	cw.UseCRLF = true
	_ = cw.Write([]string{"id", "name", "email", "created_at"})
	for _, c := range s.store.Customers(p.OrgID) {
		_ = cw.Write([]string{c.ID, c.Name, c.Email, c.CreatedAt.UTC().Format(time.RFC3339)})
	}
	cw.Flush()
}
