func TestImportCustomers(t *testing.T) {
	e := apitest.New(t)
	type result struct {
		Created int              `json:"created"`
		Items   []store.Customer `json:"items"`
	}
	body := "\xef\xbb\xbf Ignored , EMAIL ,Name,metadata.CRM_ID,default_payment_method,metadata.plan\r\n" +
		"x,jane@example.com,\"Doe, Jane \"\"JD\"\"\",7,pm_123,\"gold\r\nplus\"\r\n" +
		"\r\n" +
		"x,JOHN@example.com,John Roe,,,\n" +
		"  \n"
	var res result
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, body, &res)
	if res.Created != 2 || len(res.Items) != 2 {
		t.Fatalf("import = %+v", res)
	}
	if jane := res.Items[0]; jane.Name != `Doe, Jane "JD"` || jane.Email != "jane@example.com" || jane.DefaultPaymentMethod != "pm_123" || jane.Metadata["CRM_ID"] != "7" || jane.Metadata["plan"] != "gold\nplus" {
		t.Fatalf("jane = %+v", jane)
	}
	if john := res.Items[1]; john.Name != "John Roe" || john.DefaultPaymentMethod != "" || len(john.Metadata) != 0 {
		t.Fatalf("john = %+v", john)
	}
	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created", e.Acme.Key, nil, &evs)
	if len(evs.Items) != 2 {
		t.Fatalf("events = %+v", evs.Items)
	}

	customers := func() int {
		var page struct {
			Items []store.Customer `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/customers", e.Acme.Key, nil, &page)
		return len(page.Items)
	}
	var dry map[string]any
	e.MustDo(http.StatusOK, "POST", "/v1/customers/import?dry_run=true", e.Acme.Key, "name,email\nBo,bo@example.com\n", &dry)
	if dry["created"] != float64(0) || dry["would_create"] != float64(1) || customers() != 2 {
		t.Fatalf("dry run = %v, customers = %d", dry, customers())
	}

	for _, bad := range []string{"", "\n\n", "name,phone\nJane,1\n", "email\nx@example.com\n", "Name,Email Address\nJane,x@example.com\n"} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_header" {
			t.Fatalf("header %q: %s", bad, r)
		}
	}
	for _, bad := range []string{
		"name,email\n\"Jane,jane@example.com\n", // unterminated quote
		"name,email\nJane\n",                    // too few fields
		"name,email\nJane,jane@example.com,x\n", // too many fields
		"name,email\nJa\"ne,jane@example.com\n", // quote in an unquoted field
	} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, bad); r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_csv" {
			t.Fatalf("csv %q: %s", bad, r)
		}
	}

	bad := strings.Join([]string{
		"name,email,default_payment_method",
		`"Ann`,
		`Lee",ann@example.com,`,
		"",
		",nobody@example.com,",
		"Bo,not-an-email,",
		"Cy,cy@example.com,card_1",
		"Di,ANN@example.com,",
		"Ed,jane@example.com,",
		"Fi,fi@example.com,",
		"Gu,FI@example.com,",
		",jane@example.com,",
	}, "\n")
	var inv struct {
		Error string `json:"error"`
		Rows  []struct {
			Row   int    `json:"row"`
			Error string `json:"error"`
		} `json:"rows"`
	}
	e.MustDo(http.StatusUnprocessableEntity, "POST", "/v1/customers/import", e.Acme.Key, bad, &inv)
	want := []struct {
		row  int
		code string
	}{{5, "missing_name"}, {6, "invalid_email"}, {7, "invalid_payment_method"}, {8, "duplicate_email"}, {9, "email_taken"}, {11, "duplicate_email"}, {12, "missing_name"}}
	if inv.Error != "invalid_rows" || len(inv.Rows) != len(want) {
		t.Fatalf("invalid rows = %+v", inv)
	}
	for i, w := range want {
		if inv.Rows[i].Row != w.row || inv.Rows[i].Error != w.code {
			t.Fatalf("row %d = %+v, want %d %s", i, inv.Rows[i], w.row, w.code)
		}
	}
	if customers() != 2 {
		t.Fatalf("a refused import created customers: %d", customers())
	}
	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("dry run of a bad file: %s", r)
	}

	const maxRows = 10000 // the most data records one import may have
	csvOf := func(n int) string {
		var b strings.Builder
		b.WriteString("name,email\n")
		for i := range n {
			fmt.Fprintf(&b, "Customer %d,c%d@example.com\n", i, i)
		}
		return b.String()
	}
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, csvOf(maxRows+1)); r.Code != http.StatusRequestEntityTooLarge || r.Map(t)["error"] != "too_many_rows" {
		t.Fatalf("too many rows: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/customers/import?dry_run=true", e.Acme.Key, csvOf(maxRows), &dry)
	if dry["would_create"] != float64(maxRows) {
		t.Fatalf("dry run of the largest file = %v", dry)
	}

	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	if r := e.Do("POST", "/v1/customers/import", viewer, "name,email\nBo,bo@example.com\n"); r.Code != http.StatusForbidden {
		t.Fatalf("viewer import: %s", r)
	}
}

