func TestEmailIsUniquePerOrg(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	aJane, err := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	bJane, err := s.CreateCustomer(b.ID, "Jane B", "JANE@example.com", t0)
	if err != nil {
		t.Fatalf("the same email in another org: %v", err)
	}

	// Org A still holds the address, so an import of it is refused and nothing is created.
	if got := s.CustomerEmailsTaken(a.ID, []string{"jane@example.com"}); len(got) != 1 || got[0] != 0 {
		t.Fatalf("CustomerEmailsTaken = %v", got)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != aJane.ID {
		t.Fatalf("FindCustomerByEmail = %+v %v", got, ok)
	}
	before := len(s.Customers(a.ID))
	got, taken, err := s.CreateCustomers(a.ID, []Customer{{Name: "Jane 2", Email: "jane@example.com"}}, t0)
	if err != nil || got != nil || len(taken) != 1 || taken[0] != 0 {
		t.Fatalf("CreateCustomers = %+v, %v, %v", got, taken, err)
	}
	if n := len(s.Customers(a.ID)); n != before {
		t.Fatalf("a refused batch created %d customers", n-before)
	}

	// Deleting org B's customer leaves org A's index entry in place.
	if err := s.DeleteCustomer(b.ID, bJane.ID); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != aJane.ID {
		t.Fatalf("after another org's delete, FindCustomerByEmail = %+v %v", got, ok)
	}
}

